INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Braucht ein Dateiserver immer viel Speicherplatz?', 2, '[{"text": "Ja", "correct": true, "because": "Primär für Datenlagerung"}, {"text": "Nein", "correct": false, "because": "Kaum Ausnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für statische Webseiten?', 3, '[{"text": "Webserver", "correct": true, "because": "Liefert HTML-Inhalte"}, {"text": "Datenbankserver", "correct": false, "because": "Für dynamische Daten"}, {"text": "Dateiserver", "correct": false, "because": "Nur Speicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen einen Datenbankserver effektiv?', 5, '[{"text": "Hohe I/O-Leistung", "correct": true, "because": "Schnelle Abfragen"}, {"text": "Skalierbarkeit", "correct": true, "because": "Wachstum unterstützen"}, {"text": "Grafische Oberfläche", "correct": false, "because": "Sekundär"}, {"text": "Geringer Preis", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Webserver braucht HTTP. b) Ein Dateiserver hostet Websites.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Dateiserver speichern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Dateiserver?', 4, '[{"text": "Speicherkapazität", "correct": false, "because": "Kernaufgabe"}, {"text": "Zugriffsrechte", "correct": false, "because": "Sicherheit wichtig"}, {"text": "Hohe Grafikleistung", "correct": true, "because": "Irrelevant für Speicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Webserver auch Datenbanken hosten kann?', 2, '[{"text": "Ja", "correct": true, "because": "Kombination möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für einen Datenbankserver?', 3, '[{"text": "Schnelle SSDs", "correct": true, "because": "I/O ist entscheidend"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Sekundär"}, {"text": "Einfache GUI", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Dateiserver?', 5, '[{"text": "Zentrale Speicherung", "correct": true, "because": "Einfacher Zugriff"}, {"text": "Datensicherung", "correct": true, "because": "Backup möglich"}, {"text": "Hohe Rechenleistung", "correct": false, "because": "Nicht primär"}, {"text": "Webhosting", "correct": false, "because": "Andere Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Datenbankserver braucht viel RAM. b) Ein Webserver speichert Daten langfristig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Webserver liefern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Webserver?', 4, '[{"text": "HTTP-Unterstützung", "correct": false, "because": "Kernfunktion"}, {"text": "Netzwerkzugriff", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Hohe Speicherkapazität", "correct": true, "because": "Dateiserver-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Server mehrere Rollen haben?', 2, '[{"text": "Ja", "correct": true, "because": "Kombination üblich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für einen Webserver entscheidend?', 4, '[{"text": "Schnelle Antwortzeiten", "correct": true, "because": "Nutzererfahrung"}, {"text": "Hohe Bandbreite", "correct": true, "because": "Viele Anfragen"}, {"text": "Großer Speicher", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Dateiserver keine Datenbank braucht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Speicherung nötig"}, {"text": "Nein", "correct": false, "because": "Optional möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für einen kleinen Dateiserver?', 3, '[{"text": "Einfache Verwaltung", "correct": true, "because": "Wenig Aufwand"}, {"text": "Maximale Leistung", "correct": false, "because": "Nicht immer nötig"}, {"text": "Hohe Kosten", "correct": false, "because": "Budget zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Webserver liefert Inhalte. b) Ein Datenbankserver speichert statische Dateien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, DB für dynamische Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein kombinierter Server?', 5, '[{"text": "Ressourcenkonflikte", "correct": true, "because": "Rollen konkurrieren"}, {"text": "Single Point of Failure", "correct": true, "because": "Alles auf einem Gerät"}, {"text": "Höhere Sicherheit", "correct": false, "because": "Kein Nachteil"}, {"text": "Einfache Wartung", "correct": false, "because": "Komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Datenbankserver unwichtig?', 3, '[{"text": "RAM-Kapazität", "correct": false, "because": "Wichtig für Abfragen"}, {"text": "I/O-Geschwindigkeit", "correct": false, "because": "Kritisch für Performance"}, {"text": "Webhosting", "correct": true, "because": "Andere Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Webserver ohne Internet nutzlos?', 3, '[{"text": "Nein", "correct": true, "because": "Lokale Nutzung möglich"}, {"text": "Ja", "correct": false, "because": "Intranet denkbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Dateiserver viel CPU braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Speicherfokus, wenig Rechnung"}, {"text": "Ja", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für dynamische Inhalte?', 4, '[{"text": "Datenbankserver", "correct": true, "because": "Datenverarbeitung nötig"}, {"text": "Webserver", "correct": false, "because": "Nur Auslieferung"}, {"text": "Dateiserver", "correct": false, "because": "Statische Speicherung"}]');
